"""matplotlib.transforms — coordinate transform stubs."""

import sys as _sys
import numpy as _np


# Shared no-op fallback for unknown Transform/Bbox methods.
_transforms_warned = set()

def _transforms_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _transforms_warned:
        _transforms_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] transforms.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Transform:
    """Base transform."""
    __getattr__ = _transforms_getattr_fallback
    input_dims = 2
    output_dims = 2
    is_affine = True
    is_separable = True
    has_inverse = True

    def transform(self, values):
        return _np.asarray(values)

    def transform_affine(self, values):
        return self.transform(values)

    def transform_non_affine(self, values):
        return _np.asarray(values)

    def transform_point(self, point):
        return self.transform([point])[0]

    def transform_path(self, path):
        return path

    def transform_path_affine(self, path):
        return path

    def transform_path_non_affine(self, path):
        return path

    def transform_bbox(self, bbox):
        return bbox

    def transform_angles(self, angles, pts, radians=False, pushoff=1e-5):
        return _np.asarray(angles)

    def inverted(self):
        return self

    def get_affine(self):
        return self

    def get_matrix(self):
        return _np.eye(3)

    def contains_branch(self, other):
        return self is other

    def contains_branch_seperately(self, other_transform):
        return (False, False)

    def frozen(self):
        return self

    def __add__(self, other):
        return self

    def __sub__(self, other):
        return self

    def __eq__(self, other):
        return self is other

    def __hash__(self):
        return id(self)


class Affine2D(Transform):
    """Real 2D affine transformation backed by a 3×3 matrix.

    All transformation methods (``rotate`` / ``translate`` / ``scale`` /
    ``skew``) MUTATE the matrix in place AND return self so chaining
    works exactly like upstream matplotlib::

        Affine2D().scale(2).rotate_deg(45).translate(1, 2)
    """
    is_affine = True

    def __init__(self, matrix=None):
        self._mtx = (_np.asarray(matrix, dtype=float).copy()
                     if matrix is not None else _np.eye(3))

    def get_matrix(self):
        return self._mtx

    def set_matrix(self, mtx):
        self._mtx = _np.asarray(mtx, dtype=float).copy()
        return self

    @staticmethod
    def identity():
        return Affine2D()

    @staticmethod
    def from_values(a, b, c, d, e, f):
        """Construct from the 6 affine values (matplotlib SVG order):
        ``[[a, c, e], [b, d, f], [0, 0, 1]]``."""
        return Affine2D([[a, c, e], [b, d, f], [0, 0, 1]])

    def to_values(self):
        m = self._mtx
        return (m[0,0], m[1,0], m[0,1], m[1,1], m[0,2], m[1,2])

    def translate(self, tx, ty):
        T = _np.array([[1, 0, tx], [0, 1, ty], [0, 0, 1]], dtype=float)
        self._mtx = T @ self._mtx
        return self

    def scale(self, sx, sy=None):
        if sy is None: sy = sx
        S = _np.array([[sx, 0, 0], [0, sy, 0], [0, 0, 1]], dtype=float)
        self._mtx = S @ self._mtx
        return self

    def rotate(self, theta):
        """Rotate by ``theta`` radians counter-clockwise."""
        ca, sa = _np.cos(theta), _np.sin(theta)
        R = _np.array([[ca, -sa, 0], [sa, ca, 0], [0, 0, 1]], dtype=float)
        self._mtx = R @ self._mtx
        return self

    def rotate_deg(self, degrees):
        return self.rotate(_np.radians(degrees))

    def rotate_around(self, x, y, theta):
        self.translate(-x, -y)
        self.rotate(theta)
        self.translate(x, y)
        return self

    def rotate_deg_around(self, x, y, degrees):
        return self.rotate_around(x, y, _np.radians(degrees))

    def skew(self, xshear, yshear):
        K = _np.array([[1, _np.tan(xshear), 0],
                       [_np.tan(yshear), 1, 0],
                       [0, 0, 1]], dtype=float)
        self._mtx = K @ self._mtx
        return self

    def skew_deg(self, xshear, yshear):
        return self.skew(_np.radians(xshear), _np.radians(yshear))

    def clear(self):
        self._mtx = _np.eye(3)
        return self

    def transform(self, values):
        pts = _np.atleast_2d(_np.asarray(values, dtype=float))
        # Augment with ones column for affine math, then apply.
        ones = _np.ones((pts.shape[0], 1))
        aug = _np.hstack([pts[:, :2], ones])
        out = (self._mtx @ aug.T).T[:, :2]
        if _np.asarray(values).ndim == 1:
            return out[0]
        return out

    def transform_affine(self, values):
        return self.transform(values)

    def transform_point(self, point):
        return self.transform([point])[0]

    def inverted(self):
        try:
            inv = _np.linalg.inv(self._mtx)
        except _np.linalg.LinAlgError:
            inv = _np.eye(3)
        return Affine2D(inv)

    def frozen(self):
        return Affine2D(self._mtx.copy())

    def __add__(self, other):
        if isinstance(other, Affine2D):
            new = Affine2D(other._mtx @ self._mtx)
            return new
        return self

    def __eq__(self, other):
        if not isinstance(other, Affine2D): return False
        return _np.allclose(self._mtx, other._mtx)

    def __hash__(self):
        return id(self)

    def __repr__(self):
        return f'Affine2D({self._mtx.tolist()!r})'


class BboxBase:
    __getattr__ = _transforms_getattr_fallback


class Bbox(BboxBase):
    def __init__(self, points=None):
        self._points = _np.asarray(points) if points is not None \
                        else _np.array([[0.0, 0.0], [1.0, 1.0]])

    @staticmethod
    def from_bounds(x0, y0, width, height):
        return Bbox([[x0, y0], [x0 + width, y0 + height]])

    @staticmethod
    def from_extents(x0, y0, x1, y1):
        return Bbox([[x0, y0], [x1, y1]])

    @staticmethod
    def unit():
        return Bbox([[0.0, 0.0], [1.0, 1.0]])

    @staticmethod
    def null():
        return Bbox([[0.0, 0.0], [0.0, 0.0]])

    @property
    def x0(self): return self._points[0, 0]
    @property
    def y0(self): return self._points[0, 1]
    @property
    def x1(self): return self._points[1, 0]
    @property
    def y1(self): return self._points[1, 1]
    @property
    def width(self): return self.x1 - self.x0
    @property
    def height(self): return self.y1 - self.y0
    @property
    def xmin(self): return min(self.x0, self.x1)
    @property
    def xmax(self): return max(self.x0, self.x1)
    @property
    def ymin(self): return min(self.y0, self.y1)
    @property
    def ymax(self): return max(self.y0, self.y1)
    @property
    def bounds(self): return (self.x0, self.y0, self.width, self.height)
    @property
    def extents(self): return (self.x0, self.y0, self.x1, self.y1)
    @property
    def size(self): return (self.width, self.height)
    @property
    def min(self): return (self.xmin, self.ymin)
    @property
    def max(self): return (self.xmax, self.ymax)
    @property
    def p0(self): return tuple(self._points[0])
    @property
    def p1(self): return tuple(self._points[1])
    @property
    def intervalx(self): return (self.x0, self.x1)
    @property
    def intervaly(self): return (self.y0, self.y1)
    def get_points(self):
        return self._points
    def set_points(self, points):
        self._points = _np.asarray(points)
    def update_from_data_xy(self, xy, **kw):
        if len(xy) == 0: return
        xs = [p[0] for p in xy]
        ys = [p[1] for p in xy]
        self._points = _np.array([[min(xs), min(ys)], [max(xs), max(ys)]])
    def update_from_path(self, path, **kw):
        pass
    def contains(self, x, y):
        return (self.xmin <= x <= self.xmax) and (self.ymin <= y <= self.ymax)
    def containsx(self, x):
        return self.xmin <= x <= self.xmax
    def containsy(self, y):
        return self.ymin <= y <= self.ymax
    def overlaps(self, other):
        return not (self.xmax < other.xmin or self.xmin > other.xmax or
                    self.ymax < other.ymin or self.ymin > other.ymax)
    def transformed(self, transform):
        return self
    def expanded(self, sw, sh):
        return self
    def padded(self, p):
        return Bbox([[self.x0 - p, self.y0 - p], [self.x1 + p, self.y1 + p]])
    def translated(self, tx, ty):
        return Bbox([[self.x0 + tx, self.y0 + ty], [self.x1 + tx, self.y1 + ty]])
    def shrunk(self, sw, sh):
        return self
    def shrunk_to_aspect(self, box_aspect, *args, **kw):
        return self
    def transformed(self, transform):
        """Transform all 4 corners through ``transform`` and rebuild
        the axis-aligned bbox from their extents."""
        try:
            corners = [(self.x0, self.y0), (self.x1, self.y0),
                       (self.x1, self.y1), (self.x0, self.y1)]
            pts = transform.transform(corners)
            xs = [p[0] for p in pts]
            ys = [p[1] for p in pts]
            return Bbox([[min(xs), min(ys)], [max(xs), max(ys)]])
        except Exception:
            return self
    @staticmethod
    def union(bboxes):
        """Class-style union — matches the upstream signature exactly:
        ``Bbox.union([bbox1, bbox2, ...])`` returns the encompassing
        bbox of all inputs."""
        if not bboxes:
            return Bbox.null()
        xs = [b.x0 for b in bboxes] + [b.x1 for b in bboxes]
        ys = [b.y0 for b in bboxes] + [b.y1 for b in bboxes]
        return Bbox([[min(xs), min(ys)], [max(xs), max(ys)]])
    def intersection(self, bbox1, bbox2):
        x0 = max(bbox1.x0, bbox2.x0)
        y0 = max(bbox1.y0, bbox2.y0)
        x1 = min(bbox1.x1, bbox2.x1)
        y1 = min(bbox1.y1, bbox2.y1)
        if x1 < x0 or y1 < y0:
            return None
        return Bbox([[x0, y0], [x1, y1]])
    def frozen(self):
        return Bbox(self._points.copy())
    def __repr__(self):
        return f'Bbox(x0={self.x0}, y0={self.y0}, x1={self.x1}, y1={self.y1})'


class TransformedBbox(BboxBase):
    def __init__(self, bbox, transform):
        self._bbox = bbox
        self._transform = transform


class BlendedGenericTransform(Transform):
    def __init__(self, x_transform, y_transform):
        self._x = x_transform
        self._y = y_transform


class CompositeGenericTransform(Transform):
    def __init__(self, a, b):
        self._a = a
        self._b = b


def blended_transform_factory(x_transform, y_transform):
    return BlendedGenericTransform(x_transform, y_transform)


class ScaledTranslation(Transform):
    def __init__(self, xt, yt, scale_trans):
        self._xt = xt
        self._yt = yt


class IdentityTransform(Transform):
    pass


# ─── Added: missing transform classes ───────────────────────────
# Standard 2-D affine maths: a 3x3 homogeneous matrix [[a,b,tx],
# [c,d,ty],[0,0,1]] applied to row vectors [x, y, 1].T. Composition
# is matrix multiplication; inversion uses the analytic 2x2 inverse.
# Implementations written from scratch.

import numpy as _np2


class TransformNode:
    """Common ancestor of every transform — owns an invalidation
    timestamp so derived transforms can cache results until the
    underlying frame moves."""
    INVALID = 0
    INVALID_AFFINE = 1
    INVALID_NON_AFFINE = 2

    def __init__(self, shorthand_name=None):
        self._shorthand_name = shorthand_name
        self._invalid = self.INVALID
        self._parents = {}

    def invalidate(self):
        self._invalid = self.INVALID

    def is_affine(self): return False
    def is_bbox(self):   return False
    def set_children(self, *children): pass
    def frozen(self):    return self


class TransformWrapper(Transform):
    """Mutable wrapper — lets you swap the underlying transform at
    runtime while keeping the same external reference."""

    def __init__(self, child):
        super().__init__()
        self._child = child

    def set(self, child):       self._child = child
    def get_child(self):        return self._child
    def transform(self, values):    return self._child.transform(values)
    def inverted(self):         return self._child.inverted()


class AffineBase(Transform):
    """Affine transform base — exposes get_matrix() returning a 3x3
    numpy array. Subclasses define what's in that matrix."""

    is_affine_ = True

    def __init__(self):
        super().__init__()
        self._matrix = _np2.identity(3)

    def is_affine(self): return True
    def get_matrix(self): return self._matrix

    def transform(self, values):
        v = _np2.asarray(values, dtype=float)
        single = v.ndim == 1
        if single: v = v[None, :]
        homog = _np2.column_stack([v, _np2.ones(len(v))])
        out = homog @ self._matrix.T
        out = out[:, :2]
        return out[0] if single else out

    def inverted(self):
        inv = _np2.linalg.inv(self._matrix)
        result = AffineBase()
        result._matrix = inv
        return result


class Affine2DBase(AffineBase):
    """2-D affine — same as AffineBase but with the explicit name
    upstream uses (some user code does ``isinstance(t, Affine2DBase)``)."""
    pass


class AffineDeltaTransform(AffineBase):
    """An affine that strips the translation component of another
    affine — useful for transforming offsets (dx, dy) instead of
    positions (x, y)."""

    def __init__(self, parent):
        super().__init__()
        self._parent = parent

    def get_matrix(self):
        m = self._parent.get_matrix().copy()
        m[0, 2] = 0; m[1, 2] = 0  # zero the translation
        return m


class BlendedAffine2D(AffineBase):
    """Blended affine — x from one affine, y from another. Useful for
    mixing data-x with axes-y coordinates."""

    def __init__(self, x_transform, y_transform):
        super().__init__()
        self._x = x_transform; self._y = y_transform

    def get_matrix(self):
        mx = self._x.get_matrix() if hasattr(self._x, 'get_matrix') else _np2.identity(3)
        my = self._y.get_matrix() if hasattr(self._y, 'get_matrix') else _np2.identity(3)
        m = _np2.identity(3)
        m[0] = mx[0]; m[1] = my[1]
        return m


class CompositeAffine2D(AffineBase):
    """Composition of two affines — equivalent to applying ``a`` then
    ``b``. Matrix product: M = Mb @ Ma."""

    def __init__(self, a, b):
        super().__init__()
        self._a = a; self._b = b

    def get_matrix(self):
        ma = self._a.get_matrix() if hasattr(self._a, 'get_matrix') else _np2.identity(3)
        mb = self._b.get_matrix() if hasattr(self._b, 'get_matrix') else _np2.identity(3)
        return mb @ ma


class LockableBbox(Bbox):
    """Bbox whose individual sides can be 'locked' to fixed values
    so future mutations don't move them. Used for shared-axis figures
    where you want some bounds to remain fixed."""

    def __init__(self, bbox, x0=None, y0=None, x1=None, y1=None):
        super().__init__([[0, 0], [1, 1]])
        self._wrapped = bbox
        self._locked = {'x0': x0, 'y0': y0, 'x1': x1, 'y1': y1}

    @property
    def x0(self):
        v = self._locked['x0']
        return v if v is not None else self._wrapped.x0

    @property
    def y0(self):
        v = self._locked['y0']
        return v if v is not None else self._wrapped.y0

    @property
    def x1(self):
        v = self._locked['x1']
        return v if v is not None else self._wrapped.x1

    @property
    def y1(self):
        v = self._locked['y1']
        return v if v is not None else self._wrapped.y1


class BboxTransform(AffineBase):
    """Map from one Bbox's coordinate frame to another's — useful for
    converting data → axes → display."""

    def __init__(self, boxin, boxout):
        super().__init__()
        self._boxin = boxin
        self._boxout = boxout

    def get_matrix(self):
        bi, bo = self._boxin, self._boxout
        # Get bbox extents as floats with safe defaults.
        def _b(b):
            return (float(getattr(b, 'x0', 0)), float(getattr(b, 'y0', 0)),
                    float(getattr(b, 'x1', 1)), float(getattr(b, 'y1', 1)))
        x0i, y0i, x1i, y1i = _b(bi)
        x0o, y0o, x1o, y1o = _b(bo)
        wi = x1i - x0i or 1.0; hi = y1i - y0i or 1.0
        wo = x1o - x0o or 1.0; ho = y1o - y0o or 1.0
        sx = wo / wi; sy = ho / hi
        tx = x0o - sx * x0i
        ty = y0o - sy * y0i
        return _np2.array([[sx, 0,  tx],
                           [0,  sy, ty],
                           [0,  0,  1]])


class BboxTransformFrom(BboxTransform):
    """BboxTransform with the output box fixed to [0,1]×[0,1]."""

    def __init__(self, boxin):
        unit = Bbox([[0, 0], [1, 1]])
        super().__init__(boxin, unit)


class BboxTransformTo(BboxTransform):
    """BboxTransform with the input box fixed to [0,1]×[0,1]."""

    def __init__(self, boxout):
        unit = Bbox([[0, 0], [1, 1]])
        super().__init__(unit, boxout)


class TransformedPath(TransformNode):
    """Cache the result of applying a transform to a Path."""

    def __init__(self, path, transform):
        super().__init__()
        self._path = path
        self._transform = transform

    def get_fully_transformed_path(self):
        try:
            verts = self._transform.transform(self._path.vertices)
            from matplotlib.path import Path
            return Path(verts, getattr(self._path, 'codes', None))
        except Exception:
            return self._path

    def get_transformed_points_and_affine(self):
        return self._path, self._transform

    def get_transformed_path_and_affine(self):
        return self.get_fully_transformed_path(), self._transform


class TransformedPatchPath(TransformedPath):
    """TransformedPath that pulls its path from a Patch artist's
    `get_path()`."""

    def __init__(self, patch):
        path = patch.get_path() if hasattr(patch, 'get_path') else None
        transform = patch.get_transform() if hasattr(patch, 'get_transform') else IdentityTransform()
        super().__init__(path, transform)


def composite_transform_factory(a, b):
    """Return a ``CompositeAffine2D`` if both inputs are affine,
    else a generic CompositeGenericTransform. Mirrors upstream
    factory-style construction."""
    if isinstance(a, AffineBase) and isinstance(b, AffineBase):
        return CompositeAffine2D(a, b)
    return CompositeGenericTransform(a, b)


def interval_contains(interval, val):
    """True if ``val`` lies within ``interval = (a, b)`` regardless
    of order. Inclusive on both ends."""
    a, b = interval
    return min(a, b) <= val <= max(a, b)


def interval_contains_open(interval, val):
    """Same as ``interval_contains`` but exclusive of the endpoints."""
    a, b = interval
    return min(a, b) < val < max(a, b)


def nonsingular(vmin, vmax, expander=0.001, tiny=1e-15, increasing=True):
    """Repair a degenerate (vmin, vmax) interval. If they're equal or
    near-equal, expand outward by ``expander`` (relative). If they're
    inverted and ``increasing`` is true, swap. Returns ``(vmin, vmax)``."""
    swapped = False
    if vmin > vmax and increasing:
        vmin, vmax = vmax, vmin; swapped = True
    if abs(vmax - vmin) < tiny:
        if vmin == 0 and vmax == 0:
            vmin, vmax = -expander, expander
        else:
            mid = (vmin + vmax) * 0.5 if vmin or vmax else 0
            scale = expander * max(abs(vmin), abs(vmax), tiny)
            vmin = mid - scale; vmax = mid + scale
    if swapped and not increasing:
        return vmax, vmin
    return vmin, vmax


def offset_copy(trans, fig=None, x=0.0, y=0.0, units='inches'):
    """Return a copy of ``trans`` with a translation appended.
    ``units`` may be 'inches', 'points', or 'dots' — converted to the
    figure's coordinate system if a figure is supplied."""
    if fig is not None and units != 'dots':
        dpi = float(getattr(fig, 'dpi', 100))
        if units == 'inches':
            x *= dpi; y *= dpi
        elif units == 'points':
            x *= dpi / 72.0; y *= dpi / 72.0
    result = CompositeAffine2D(trans, AffineBase())
    # Build a translation affine.
    t = AffineBase()
    t._matrix = _np2.array([[1, 0, x], [0, 1, y], [0, 0, 1]])
    return CompositeAffine2D(trans, t)


# ─── Added: misc public names from upstream transforms.py ──────────


# Upstream uses this flag to dump bbox debug info — surface it so
# external code that toggles it doesn't AttributeError.
DEBUG = False


class BboxTransformToMaxOnly(AffineBase):
    """Transform that scales to the *maximum* extent of an output Bbox
    while keeping the origin pinned. Used by upstream for layout cases
    where only the upper bound matters."""

    def __init__(self, boxout):
        super().__init__()
        self.boxout = boxout

    def get_matrix(self):
        import numpy as _np
        x = getattr(self.boxout, 'x1', 1.0)
        y = getattr(self.boxout, 'y1', 1.0)
        # Scale only — no translation.
        return _np.array([[x, 0, 0], [0, y, 0], [0, 0, 1]], dtype=float)


