def _attach_transform_methods():
    """Add the rest of the upstream Transform API to AffineBase + its
    children. Mostly identity-returning helpers and shape introspection."""

    def has_inverse(self):       return True
    def contains_branch(self, other): return self is other
    def contains_branch_seperately(self, other): return (False, False)
    def depth(self):             return 1
    def frozen(self):            return self
    def get_affine(self):        return self
    def is_separable_attr(self): return False
    def transform_path(self, path):
        return path
    def transform_path_affine(self, path):
        return path
    def transform_path_non_affine(self, path):
        return path
    def transform_bbox(self, bbox):
        return bbox
    def transform_point(self, point):
        return tuple(self.transform([point])[0])
    def inverse_transform(self, values):
        return self.inverted().transform(values)
    def __add__(self, other):
        return self  # Composition handled by composite_transform_factory
    def __sub__(self, other):
        return self
    def __eq__(self, other):
        return type(self) is type(other)
    def __hash__(self):
        return hash(type(self))

    for cls in (AffineBase, Affine2DBase):
        cls.has_inverse                  = has_inverse
        cls.contains_branch              = contains_branch
        cls.contains_branch_seperately   = contains_branch_seperately
        cls.depth                        = depth
        cls.frozen                       = frozen
        cls.get_affine                   = get_affine
        cls.transform_path               = transform_path
        cls.transform_path_affine        = transform_path_affine
        cls.transform_path_non_affine    = transform_path_non_affine
        cls.transform_bbox               = transform_bbox
        cls.transform_point              = transform_point
        cls.inverse_transform            = inverse_transform


_attach_transform_methods()


# ── Affine2D class with mutable matrix ────────────────────────────


class Affine2D(AffineBase):
    """Mutable 2-D affine transform — the type most users construct via
    ``Affine2D().rotate_deg(45).scale(2, 3)``. Stores a 3x3 matrix and
    chains common transforms."""

    def __init__(self, matrix=None):
        super().__init__()
        import numpy as _np
        self._matrix = (_np.asarray(matrix, dtype=float) if matrix is not None
                         else _np.eye(3))

    def get_matrix(self):
        return self._matrix.copy()

    def set_matrix(self, mat):
        import numpy as _np
        self._matrix = _np.asarray(mat, dtype=float)
        return self

    def clear(self):
        import numpy as _np
        self._matrix = _np.eye(3)
        return self

    def set(self, other):
        self._matrix = other.get_matrix()
        return self

    @staticmethod
    def from_values(a, b, c, d, e, f):
        import numpy as _np
        return Affine2D(_np.array([[a, c, e], [b, d, f], [0, 0, 1]]))

    @staticmethod
    def identity():
        return Affine2D()

    def translate(self, tx, ty):
        import numpy as _np
        T = _np.array([[1, 0, tx], [0, 1, ty], [0, 0, 1]], dtype=float)
        self._matrix = T @ self._matrix
        return self

    def scale(self, sx, sy=None):
        import numpy as _np
        if sy is None: sy = sx
        S = _np.diag([sx, sy, 1.0])
        self._matrix = S @ self._matrix
        return self

    def rotate(self, theta):
        import numpy as _np, math
        c, s = math.cos(theta), math.sin(theta)
        R = _np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])
        self._matrix = R @ self._matrix
        return self

    def rotate_deg(self, deg):
        import math
        return self.rotate(math.radians(deg))

    def rotate_around(self, x, y, theta):
        return self.translate(-x, -y).rotate(theta).translate(x, y)

    def rotate_deg_around(self, x, y, deg):
        import math
        return self.rotate_around(x, y, math.radians(deg))

    def skew(self, x_shear, y_shear):
        import numpy as _np, math
        K = _np.array([[1, math.tan(x_shear), 0],
                        [math.tan(y_shear), 1, 0],
                        [0, 0, 1]])
        self._matrix = K @ self._matrix
        return self

    def skew_deg(self, x_shear, y_shear):
        import math
        return self.skew(math.radians(x_shear), math.radians(y_shear))

    def inverted(self):
        import numpy as _np
        return Affine2D(_np.linalg.inv(self._matrix))


# ── IdentityTransform ─────────────────────────────────────────────


class IdentityTransform(AffineBase):
    """The identity 2-D transform — ``transform(x) == x``."""

    def get_matrix(self):
        import numpy as _np
        return _np.eye(3)
    def transform_affine(self, values):
        import numpy as _np
        return _np.asarray(values)
    def transform_non_affine(self, values):
        import numpy as _np
        return _np.asarray(values)
    def transform_path(self, path):
        return path
    def transform_path_affine(self, path):
        return path
    def transform_path_non_affine(self, path):
        return path
    def get_affine(self):    return self
    def frozen(self):        return self
    def has_inverse(self):   return True
    def inverted(self):
        return IdentityTransform()


# ── CompositeGenericTransform / BlendedGenericTransform ───────────


class CompositeGenericTransform(AffineBase):
    """Composition ``a → b`` of two transforms — applies ``a`` then ``b``."""

    def __init__(self, a, b):
        super().__init__()
        self._a, self._b = a, b

    def transform(self, values):
        return self._b.transform(self._a.transform(values))

    def inverted(self):
        return CompositeGenericTransform(self._b.inverted(), self._a.inverted())

    def has_inverse(self): return True
    def contains_branch(self, other): return self._a is other or self._b is other
    def contains_branch_seperately(self, other):
        return (self._a is other, self._b is other)
    def depth(self): return getattr(self._a, 'depth', lambda: 1)() + \
                            getattr(self._b, 'depth', lambda: 1)()
    def frozen(self):    return self
    def get_affine(self):
        return self
    def is_separable(self):
        return False


class BlendedGenericTransform(AffineBase):
    """Use one transform for x, another for y. Output is the union."""

    def __init__(self, x_transform, y_transform):
        super().__init__()
        self._x_transform = x_transform
        self._y_transform = y_transform

    def transform(self, values):
        import numpy as _np
        arr = _np.asarray(values, dtype=float)
        if arr.ndim == 1:
            xs = self._x_transform.transform([arr[0]])[0]
            ys = self._y_transform.transform([arr[1]])[0]
            return _np.array([xs, ys])
        xs = self._x_transform.transform(arr[:, [0]])
        ys = self._y_transform.transform(arr[:, [1]])
        return _np.column_stack([xs[:, -1], ys[:, -1]])

    def has_inverse(self): return True
    def contains_branch(self, other):
        return self._x_transform is other or self._y_transform is other
    def depth(self): return 1
    def frozen(self): return self
    def get_affine(self): return self
    def is_separable(self): return True
    def inverted(self):
        return BlendedGenericTransform(self._x_transform.inverted(),
                                        self._y_transform.inverted())


